const lead   = $('Get Lead (Supabase)').first().json  || {};
const deal   = $('Get Deal (Supabase)').first().json   || {};

// ── Lead data
const leadName    = lead.full_name || lead.name || 'the client';
const leadCompany = lead.company   || '';
const leadEmail   = lead.email     || '';

// ── Consultant data
const webhookBody     = $('Webhook Deal Won').first().json.body || {};
const consultantName  = webhookBody.consultant_name  || 'the consultant';
const consultantEmail = webhookBody.consultant_email || '';
const locale          = webhookBody.locale || lead.locale || 'fr';
const LANG_MAP = { en:'English', fr:'French', es:'Spanish', ar:'Arabic', pt:'Portuguese', de:'German' };
const language = LANG_MAP[locale] || 'French';

// ── Deal data
const serviceName = deal.service_name || deal.name || 'the contracted service';
const dealValue   = deal.amount || deal.price || '';
const dealNotes   = deal.notes || '';

// ── Audit context — supports v2 (named blocks) and v1 (audit_blocks[]) ──
const auditJson = lead.ai_analysis_json || {};
const stripH = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
let auditContext = 'No prior audit available.';

if (auditJson.version === 2 || auditJson.context_block) {
  const parts = [];
  if (auditJson.hero?.headline) parts.push(`[Score: ${auditJson.hero.score || '?'}/100] ${auditJson.hero.headline}`);
  if (auditJson.context_block?.content) parts.push(`[Contexte] ${stripH(auditJson.context_block.content).substring(0, 400)}`);
  if (Array.isArray(auditJson.solutions_block?.items)) {
    parts.push('[Solutions recommandées] ' + auditJson.solutions_block.items.map(i => i.title).join(', '));
  }
  auditContext = parts.join('\n') || auditContext;
} else {
  const auditBlocks = Array.isArray(auditJson.audit_blocks) ? auditJson.audit_blocks : [];
  auditContext = auditBlocks
    .filter(b => ['intro','recos','forts'].includes(b.id))
    .map(b => `[${b.title}]: ${stripH(b.content).substring(0, 400)}`)
    .join('\n') || auditContext;
}

// ── Form answers (what the client originally filled in)
const formAnswers = JSON.stringify(lead.static_answers || lead.respondent_info || {});

const prompt =
`<s>
You are an expert professional onboarding specialist and UX form designer.
Your mission: design a precise, complete Kickoff form to collect EVERYTHING needed to deliver "${serviceName}" to a new client.
The form must feel professional, organized, and respectful of the client's time.
Reason internally before generating. Output language: ${language}. ALL user-visible text in ${language}.
</s>

<context>
Client: ${leadName}${leadCompany ? ' (' + leadCompany + ')' : ''}
Contracted service: ${serviceName}${dealValue ? ' — ' + dealValue : ''}
Consultant: ${consultantName}

What we already know about the client (from their initial form):
${formAnswers}

Key insights from prior audit:
${auditContext}

${dealNotes ? 'Deal notes: ' + dealNotes : ''}
</context>

<contraintes_juridiques_contrat_fr>
When relevant to the contracted service, ensure questions allow collecting data required to secure: scope clarity, timeline, pricing assumptions, responsibilities, confidentiality, and intellectual property transfer conditions.
Do not provide legal advice text to the client.
</contraintes_juridiques_contrat_fr>

<protocole_raisonnement_structure>
Reason internally, then provide a concise visible rationale_summary for the client.
This summary must explain framing choices and next step, without exposing hidden chain-of-thought.
</protocole_raisonnement_structure>

<quality_gate>
If the input is LOW quality, do not repeat unknown fields; ask only for the minimum needed information.
If the input is MEDIUM quality, infer sparingly and flag assumptions in the rationale_summary.
If the input is HIGH quality, use the data fully but stay within the requested scope.
Never ask for information already collected in the initial answers.
</quality_gate>



<kickoff_form_strategy>
Design the form in 3 logical sections:

SECTION 1 — ACCESS & CREDENTIALS
Collect all technical access, logins, and assets the consultant needs to start.
Examples: website URL, CMS access, social media handles, Google Analytics, ad accounts, existing assets, etc.
Adapt to the service: "${serviceName}" — only ask for what is ACTUALLY needed for this service.

SECTION 2 — STRATEGIC BRIEF
Collect the key strategic information to personalize the deliverables.
Examples: target audience, key competitors, main goals, current challenges, brand voice, key messages, constraints.
These should deepen understanding of what was already collected — no repetition.

SECTION 3 — OPERATIONAL LOGISTICS
Collect working preferences and logistics.
Examples: preferred communication channel, availability for calls, project timeline, urgent priorities, stakeholders involved.

FIELD TYPES AVAILABLE: text | textarea | select | radio | checkbox | email | phone | url | number | date | file | section
- "section" type MUST have sectionTitle and empty label (groups questions visually)
- select/radio/checkbox MUST have options array (2-5 choices)
- Use "url" for website and link inputs, "date" for deadline inputs, "file" for document uploads
</kickoff_form_strategy>

<rules>
1. Generate 12-18 questions (sections not counted) — enough to be thorough, not overwhelming.
2. NEVER ask for information already collected in the client's initial form answers.
3. Every question must be directly necessary to deliver "${serviceName}" — no filler questions.
4. form_title: MAX 6 words, professional and welcoming.
5. form_description: MAX 40 words, explain why this form matters and set expectations.
6. thank_you_title: MAX 4 words.
7. thank_you_description: MAX 35 words, state exact next step and timeframe (e.g., "We'll review your answers and reach out within 48 hours to kick off your project.").
8. Output ONLY valid raw JSON. No markdown. No preamble.
</rules>

<output_format>
{
  "form_title": "string — max 6 words",
  "form_description": "string — max 40 words",
  "questions": [
    { "type": "section",   "sectionTitle": "Section name",              "label": "",                    "required": false },
    { "type": "url",       "label": "Website or relevant URL?",         "placeholder": "https://...",   "required": true  },
    { "type": "text",      "label": "Short answer question?",           "placeholder": "Your answer...", "required": true  },
    { "type": "textarea",  "label": "Detailed open question?",          "placeholder": "Describe...",   "required": false },
    { "type": "select",    "label": "Choice question?",                  "options": ["A", "B", "C"],    "required": true  },
    { "type": "file",      "label": "Upload relevant document?",        "placeholder": "",              "required": false }
  ],
  "thank_you_title": "string — max 4 words",
  "thank_you_description": "string - max 35 words with next step and timeframe",
  "rationale_summary": {
    "framing_choice": "1 short paragraph",
    "contractual_points_to_validate": ["point 1", "point 2"],
    "next_step": "1 sentence"
  }
}
</output_format>`;

return [{
  json: {
    generated_prompt: prompt,
    lead_id: lead.id,
    user_id: lead.user_id,
    client_name: leadName,
    consultant_name: consultantName,
    service_name: serviceName,
    language
  }
}];

const response = $input.first().json;
let content = response.text || '';

content = content.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
const fenceS = content.indexOf('```');
if (fenceS !== -1) {
  const fenceE = content.lastIndexOf('```');
  if (fenceE > fenceS) {
    const al = content.indexOf('\n', fenceS);
    content = content.substring(al > -1 ? al + 1 : fenceS + 3, fenceE).trim();
  }
}

const s = content.indexOf('{'); const e = content.lastIndexOf('}');
let parsed;
try {
  parsed = JSON.parse(s !== -1 && e > s ? content.substring(s, e + 1) : content);
} catch(err) {
  throw new Error('KICKOFF_PARSE_FAILED: Gemini returned invalid JSON. Raw: ' + content.substring(0, 200));
}

if (!Array.isArray(parsed.questions) || parsed.questions.length === 0) {
  throw new Error('KICKOFF_SCHEMA_ERROR: questions array missing or empty');
}

const payload = $('Prepare Kickoff Prompt').first().json;
const slug = 'kickoff-' + (payload.lead_id || 'x') + '-' + Date.now();
const rationaleSummary = (() => {
  const rs = parsed.rationale_summary;
  if (typeof rs === 'string') {
    return { framing_choice: rs, contractual_points_to_validate: [], next_step: '' };
  }
  return {
    framing_choice: rs?.framing_choice || '',
    contractual_points_to_validate: Array.isArray(rs?.contractual_points_to_validate) ? rs.contractual_points_to_validate.slice(0, 4) : [],
    next_step: rs?.next_step || ''
  };
})();

return [{
  json: {
    user_id:         payload.user_id,
    title:           parsed.form_title || 'Kickoff Onboarding',
    slug:            slug,
    status:          'published',
    is_public:       true,
    form_structure:  { ...parsed, rationale_summary: rationaleSummary },
    consultant_name: payload.consultant_name || 'Consultant',
    client_name:     payload.client_name,
    lead_id:         payload.lead_id
  }
}];
